import{_ as t,o as a,c as n,a2 as s}from"./chunks/framework.CDU0sSpB.js";const u=JSON.parse('{"title":"Runtime and Safety","description":"How Hearth limits real-world impact through workspaces, isolation, network egress, credentials, privacy, supply chain, and device loss.","frontmatter":{"title":"Runtime and Safety","description":"How Hearth limits real-world impact through workspaces, isolation, network egress, credentials, privacy, supply chain, and device loss.","outline":false},"headers":[],"relativePath":"en/design/safety.md","filePath":"en/design/safety.md","lastUpdated":null}'),r={name:"en/design/safety.md"};function o(d,e,i,l,c,h){return a(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="runtime-and-safety" tabindex="-1">Runtime and Safety <a class="header-anchor" href="#runtime-and-safety" aria-label="Permalink to &quot;Runtime and Safety&quot;">​</a></h1><p class="lead">Security is not a layer added at the end. It is the precondition for a product that touches real files, accounts, and devices on the user&#39;s behalf. Hearth grants only the minimum needed for the task and withdraws temporary capability when the task ends.</p><h2 id="design-goals" tabindex="-1">Design Goals <a class="header-anchor" href="#design-goals" aria-label="Permalink to &quot;Design Goals&quot;">​</a></h2><p>The execution environment must distinguish what can be read, written, sent over the network, and accessed through credentials. Research can be read-only. Code and document work uses a recoverable workspace. Untrusted files enter isolation. Work that needs a specific device runs only on that device. Temporary authority, file mounts, and network rules cannot remain forever.</p><p>Network access is denied by default; only domains and ports explicitly needed by the task are opened. Access is logged through a proxy, local management interfaces and cloud metadata addresses are blocked, and downloads enter quarantine before scanning and parsing. Attempts to bypass network restrictions are security incidents, not ordinary failures.</p><p>Credentials are managed behind a separate boundary. Models and executors never see long-lived passwords, refresh tokens, or complete secrets. They receive short-lived capabilities for the task and scope. Connectors inject credentials when calling an external service, and use is audited, redacted, and revocable.</p><p>Local-first is part of privacy design. Personal files, memory, events, and credentials remain in an environment the user controls by default. When remote models, remote execution, or cloud sync are used, the system states which data leaves the device, how long it is retained, whether it can be deleted, and how it can be exported.</p><h2 id="design-tradeoffs" tabindex="-1">Design Tradeoffs <a class="header-anchor" href="#design-tradeoffs" aria-label="Permalink to &quot;Design Tradeoffs&quot;">​</a></h2><p>Workspaces are chosen by task risk rather than sharing one large directory. Read-only workspaces support research and review. Disposable workspaces are destroyed when the task ends. Copy-on-write workspaces preserve originals and support diffs and rollback. Long-lived project workspaces have versions, quotas, and cleanup rules. Remote device workspaces use encrypted transfer and short-lived authority.</p><table tabindex="0"><thead><tr><th>Isolation method</th><th>Suitable for</th><th>Limitation</th></tr></thead><tbody><tr><td>Restricted process</td><td>Trusted scripts and lightweight tools</td><td>Not a strong boundary against malicious code</td></tr><tr><td>Container</td><td>General code, tests, and document conversion</td><td>Shares the kernel and is not absolute protection</td></tr><tr><td>Lightweight virtual machine</td><td>Untrusted code, external files, and high-risk research</td><td>Higher startup and resource cost</td></tr><tr><td>Virtual desktop</td><td>Graphical software and untrusted desktop apps</td><td>Complex to operate and still needs network and credential control</td></tr><tr><td>Remote device</td><td>Operations that must happen on a particular device</td><td>Loss, offline state, and revocation need separate handling</td></tr></tbody></table><p>Containers are useful operational isolation, not an absolute guarantee against malicious code. Macros, downloads, browser pages, external code, and high-risk documents need stronger isolation. The safety level follows task source, data sensitivity, reversibility, and external impact, not just the executor type.</p><p>Credentials never enter the model context. Hearth grants short-lived capability by account, resource, action, device, and time, then revokes it when the task ends. Logs, errors, and model inputs are redacted automatically. Users can see which connections remain active and revoke all grants at once.</p><p>Supply chain and device safety are product boundaries too. Dependencies are pinned, audited, and minimized. Extensions do not receive all permissions by default. Device pairing declares identity and capability, and a lost device can be revoked, have keys rotated, and have local data cleared. A serious incident needs a global pause and isolation entry, not only one-by-one task cancellation.</p>',13)])])}const m=t(r,[["render",o]]);export{u as __pageData,m as default};
